// Generated by local model ornith:9b (no-think), reviewed + tested by Claude.
export type DataStatusTone = "ok" | "warn" | "bad" | "unknown";

export function describeDataStatus(s: any): { tone: DataStatusTone; label: string; detail: string } {
  const status = s?.status ?? "UNKNOWN";
  const session = s?.session ?? "";
  const coverage = s?.data_quality?.official_coverage;
  const d = formatDate(session);

  switch (status) {
    case "OK":
      return { tone: "ok", label: `Data as of ${d}`, detail: "Official exchange close" };
    case "DEGRADED": {
      const pct = coverage != null && coverage >= 0 && coverage <= 1 ? Math.round(coverage * 100) : 0;
      if (pct > 0) return { tone: "warn", label: `Data as of ${d} · partial`, detail: `${pct}% of stocks have official prices` };
      return { tone: "warn", label: `Data as of ${d} · partial`, detail: "Some stocks still have provisional prices" };
    }
    case "FAILED":
      return { tone: "bad", label: `Data under review (${d})`, detail: "Today's exchange data failed our checks. New AI trades are paused; treat today's scan with caution." };
    default:
      return { tone: "unknown", label: "Data status unavailable", detail: "" };
  }
}

function formatDate(session: string): string {
  try {
    if (!session) return "—";
    const parsed = new Date(session);
    if (isNaN(parsed.getTime())) return "—";
    return parsed.toLocaleDateString("en-IN", { day: "numeric", month: "short" });
  } catch {
    return "—";
  }
}
